In React Router v6 you use a wrapper component rather than `onEnter` hooks:

```tsx
import { Navigate, Outlet } from 'react-router-dom';

interface RequireAuthProps {
  isAuthenticated: boolean;
  redirectTo?: string;
}

export function RequireAuth({ isAuthenticated, redirectTo = '/login' }: RequireAuthProps) {
  return isAuthenticated ? <Outlet /> : <Navigate to={redirectTo} replace />;
}
```

Then wrap your protected routes:

```tsx
<Routes>
  <Route element={<RequireAuth isAuthenticated={!!user} />}>
    <Route path="/dashboard" element={<Dashboard />} />
    <Route path="/settings" element={<Settings />} />
  </Route>
  <Route path="/login" element={<Login />} />
</Routes>
```

Pass the current location through state and redirect back after login:

```tsx
// RequireAuth — save attempted location
import { Navigate, Outlet, useLocation } from 'react-router-dom';

export function RequireAuth({ isAuthenticated }: { isAuthenticated: boolean }) {
  const location = useLocation();
  return isAuthenticated
    ? <Outlet />
    : <Navigate to="/login" state={{ from: location }} replace />;
}
```

```tsx
// Login page — read saved location and redirect after success
import { useNavigate, useLocation } from 'react-router-dom';

export function Login() {
  const navigate = useNavigate();
  const location = useLocation();
  const from = (location.state as { from?: Location })?.from?.pathname ?? '/';

  async function handleSubmit(credentials: Credentials) {
    await login(credentials);
    navigate(from, { replace: true });
  }
  // ...
}
